metadata.er-schema:
{
  "title": "looply · 支付打款模块 实体关系图",
  "version": "v1.0 · 2026-09-02",
  "tables": [
    {
      "name": "payout_funding_account",
      "comment": "资金账户",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "account_no",
          "comment": "资金账户编号（摩根侧账户标识）",
          "constraint": "UNIQUE"
        },
        {
          "name": "account_name",
          "comment": "账户名称",
          "constraint": ""
        },
        {
          "name": "channel",
          "comment": "所属渠道（jpmorgan）",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "available_balance",
          "comment": "可用余额（摩根侧同步值，非权威）",
          "constraint": ""
        },
        {
          "name": "balance_synced_at",
          "comment": "余额同步时间",
          "constraint": ""
        },
        {
          "name": "warning_threshold",
          "comment": "余额预警阈值",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "账户状态（启用/停用）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生。looply 在摩根开立的出款资金账户。V1 仅一个 USD 账户，available_balance 是摩根侧余额的本地同步值，仅用于列表展示与预警；打款前的余额校验以摩根实时查询结果为准（见设计规则 balance_check）。"
    },
    {
      "name": "payout_deposit",
      "comment": "预充值单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "deposit_no",
          "comment": "充值单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "funding_account_id",
          "comment": "目标资金账户（→ payout_funding_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "amount",
          "comment": "充值金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "deposit_method",
          "comment": "充值方式（银行转账/内部划转）",
          "constraint": ""
        },
        {
          "name": "external_ref",
          "comment": "外部凭证号（银行回单号/摩根入账编号）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "充值状态（待到账/已到账/充值失败）",
          "constraint": ""
        },
        {
          "name": "confirmed_at",
          "comment": "到账确认时间",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "操作人（运营）",
          "constraint": ""
        },
        {
          "name": "remark",
          "comment": "备注",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生。运营发起的一次资金池充值。资金实际到账由运营在摩根侧确认后回填，系统不自动判定到账（V1 无摩根入账回调，见待确认项 W3）。"
    },
    {
      "name": "payout_balance_change",
      "comment": "余额变动明细",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "funding_account_id",
          "comment": "资金账户（→ payout_funding_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "change_type",
          "comment": "变动类型（充值入账/打款出账/打款失败退回）",
          "constraint": ""
        },
        {
          "name": "change_amount",
          "comment": "变动金额（入账为正、出账为负）",
          "constraint": ""
        },
        {
          "name": "balance_before",
          "comment": "变动前余额",
          "constraint": ""
        },
        {
          "name": "balance_after",
          "comment": "变动后余额",
          "constraint": ""
        },
        {
          "name": "ref_type",
          "comment": "关联单据类型（充值单/打款单）",
          "constraint": ""
        },
        {
          "name": "ref_id",
          "comment": "关联单据 ID",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "变动时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生。资金台账，每一行是一次真实的资金增减事实（非操作留痕）。财务按此追溯资金池每一分钱的来源与去向。balance_before 与 balance_after 记录变动前后余额，用于事后核对连续性。"
    },
    {
      "name": "payout_order",
      "comment": "打款单",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "payout_no",
          "comment": "打款单号",
          "constraint": "UNIQUE"
        },
        {
          "name": "funding_account_id",
          "comment": "出款资金账户（→ payout_funding_account）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "channel",
          "comment": "打款渠道（jpmorgan）",
          "constraint": ""
        },
        {
          "name": "payout_method",
          "comment": "打款方式（zelle / paypal / venmo / rtp）",
          "constraint": ""
        },
        {
          "name": "payee_name",
          "comment": "收款人姓名（通道校验用）",
          "constraint": ""
        },
        {
          "name": "payee_alias",
          "comment": "收款别名（邮箱或手机号；zelle/paypal/venmo 用，加密存储）",
          "constraint": ""
        },
        {
          "name": "payee_bank_routing_number",
          "comment": "银行路由号（rtp 用，加密存储）",
          "constraint": ""
        },
        {
          "name": "payee_bank_account_number",
          "comment": "银行账号（rtp 用，加密存储）",
          "constraint": ""
        },
        {
          "name": "payee_bank_name",
          "comment": "开户行名称（由路由号反查所得，供录入时回显确认）",
          "constraint": ""
        },
        {
          "name": "payee_masked",
          "comment": "收款信息脱敏值（由明文派生，界面与导出只用此值）",
          "constraint": ""
        },
        {
          "name": "amount",
          "comment": "打款金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "打款单状态（见设计规则 payout_order_status）",
          "constraint": ""
        },
        {
          "name": "paid_at",
          "comment": "打款成功时间",
          "constraint": ""
        },
        {
          "name": "remark",
          "comment": "业务备注（自由文本，本单唯一业务追溯依据）",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "录入人（运营）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生。一笔应付给 C 端个人卖家的款项，由运营在后台手工录入（A6：本期无回收单、无上游系统对接）。结构对齐订单支付 payment_order（A12）。收款信息以快照形式随单存储、不建收款人档案（A8）；payee_alias 与 payee_bank_ 两组字段按 payout_method 二选一存值。remark 是本单唯一的业务追溯依据（A9）。"
    },
    {
      "name": "payout_transaction",
      "comment": "打款流水",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "transaction_no",
          "comment": "内部流水号",
          "constraint": "UNIQUE"
        },
        {
          "name": "payout_order_id",
          "comment": "所属打款单（→ payout_order）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "transaction_type",
          "comment": "交易类型（payout；与支付流水同一取值域）",
          "constraint": ""
        },
        {
          "name": "channel_transaction_id",
          "comment": "渠道交易号（对账匹配键）",
          "constraint": "UNIQUE"
        },
        {
          "name": "amount",
          "comment": "交易金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "channel_fee",
          "comment": "渠道手续费",
          "constraint": ""
        },
        {
          "name": "channel_fee_currency",
          "comment": "手续费币种",
          "constraint": ""
        },
        {
          "name": "net_amount",
          "comment": "实际出账金额",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "流水状态（打款中/成功/失败）",
          "constraint": ""
        },
        {
          "name": "failure_reason",
          "comment": "失败原因分类（见设计规则 failure_handling）",
          "constraint": ""
        },
        {
          "name": "channel_raw_data",
          "comment": "渠道原始响应（JSON）",
          "constraint": ""
        },
        {
          "name": "reconciliation_status",
          "comment": "对账状态（待结算/已结算，与订单支付同枚举）",
          "constraint": ""
        },
        {
          "name": "reconciled_at",
          "comment": "对账时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生。每向摩根发起一次打款指令产生一条，一张打款单可有多条（失败重发）。字段与订单支付 payment_transaction 一一对应（A12），transaction_type 取值 payout，将来两模块合并时可直接 UNION、无需字段映射。channel_transaction_id 是与摩根结算数据的对账匹配键。"
    },
    {
      "name": "payout_settlement_record",
      "comment": "渠道结算记录",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "channel",
          "comment": "渠道（jpmorgan）",
          "constraint": ""
        },
        {
          "name": "settlement_date",
          "comment": "结算日期",
          "constraint": ""
        },
        {
          "name": "channel_transaction_id",
          "comment": "渠道交易号（匹配键）",
          "constraint": ""
        },
        {
          "name": "channel_amount",
          "comment": "渠道侧金额",
          "constraint": ""
        },
        {
          "name": "channel_fee",
          "comment": "渠道侧手续费",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "channel_status",
          "comment": "渠道侧交易状态（原样保留）",
          "constraint": ""
        },
        {
          "name": "payout_transaction_id",
          "comment": "匹配到的本方流水（→ payout_transaction；未匹配时无值）",
          "constraint": "FOREIGN KEY"
        },
        {
          "name": "match_status",
          "comment": "匹配状态（已匹配/我方无此笔/金额不符）",
          "constraint": ""
        },
        {
          "name": "handle_status",
          "comment": "差错处理状态（待处理/处理中/已闭环）",
          "constraint": ""
        },
        {
          "name": "handle_note",
          "comment": "差错处理说明",
          "constraint": ""
        },
        {
          "name": "handled_by",
          "comment": "处理人（运营）",
          "constraint": ""
        },
        {
          "name": "handled_at",
          "comment": "处理时间",
          "constraint": ""
        },
        {
          "name": "pulled_at",
          "comment": "数据拉取时间",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生（数据源为摩根）。日终从摩根拉回的逐笔结算数据，按 channel_transaction_id 与本方流水匹配。匹配不上的记录留在本表，是「摩根侧有、我方无」这类差异的唯一落点。差错处理结论也记在本表，构成对账闭环。"
    },
    {
      "name": "payout_limit_config",
      "comment": "限额配置",
      "columns": [
        {
          "name": "id",
          "comment": "主键",
          "constraint": "PRIMARY KEY"
        },
        {
          "name": "limit_type",
          "comment": "限额类型（单笔上限/单日累计上限/单操作人单日上限）",
          "constraint": ""
        },
        {
          "name": "limit_scope",
          "comment": "适用范围（全局/按打款方式）",
          "constraint": ""
        },
        {
          "name": "payout_method",
          "comment": "适用打款方式（limit_scope 为按打款方式时取值）",
          "constraint": ""
        },
        {
          "name": "limit_amount",
          "comment": "限额金额",
          "constraint": ""
        },
        {
          "name": "currency_code",
          "comment": "币种（ISO 4217）",
          "constraint": ""
        },
        {
          "name": "status",
          "comment": "启用状态（启用/停用）",
          "constraint": ""
        },
        {
          "name": "operator_id",
          "comment": "最后修改人（运营）",
          "constraint": ""
        },
        {
          "name": "created_at",
          "comment": "创建时间",
          "constraint": ""
        },
        {
          "name": "updated_at",
          "comment": "更新时间",
          "constraint": ""
        }
      ],
      "note": "本模块产生。A2 定「不设人工审核」，限额是本模块唯一的事前内控手段，因此必须可配置、可审计。一行一条限额规则，打款单提交时逐条校验，任一不通过即拦截。"
    }
  ],
  "relations": [
    {
      "from": "payout_deposit",
      "to": "payout_funding_account",
      "type": "N:1",
      "label": "充入",
      "color": "#1565C0",
      "penwidth": 1.4
    },
    {
      "from": "payout_balance_change",
      "to": "payout_funding_account",
      "type": "N:1",
      "label": "记录变动",
      "color": "#1565C0"
    },
    {
      "from": "payout_order",
      "to": "payout_funding_account",
      "type": "N:1",
      "label": "从此账户出款",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "payout_transaction",
      "to": "payout_order",
      "type": "N:1",
      "label": "每次发起一条（失败可重发）",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "payout_settlement_record",
      "to": "payout_transaction",
      "type": "N:1",
      "label": "按渠道交易号匹配",
      "color": "#3F9A72",
      "style": "dashed"
    }
  ],
  "design_rules": {
    "scope_v1": "V1 范围：运营后台充值资金池、手工录入打款单、经 zelle / paypal / venmo / rtp 四种方式出款、全量流水与日终对账。不含回收单、卖家自助入口、人工审核、税务采集、对外通知。",
    "isomorphism_a12": "与订单支付三处同构（决策 A12）：① payout_order 字段命名对齐 payment_order；② payout_transaction 与 payment_transaction 字段一一对应，transaction_type 取值 payout，与支付侧 payment / refund 同属一个取值域，将来合并可直接 UNION；③ reconciliation_status 沿用订单支付对账枚举（待结算/已结算），不另立一套。新增字段仅两处：failure_reason（打款失败分类）与 payee_ 系列（收款信息快照），因支付侧无对应概念。",
    "balance_check": "打款前余额校验（决策 A3）：以摩根侧实时查询结果为准，payout_funding_account.available_balance 仅供列表展示与预警，不作为放行依据。余额不足时打款单直接置失败，不进入排队等待补款。",
    "balance_ledger": "资金池余额的每一次增减都要在 payout_balance_change 落一行，并回填 balance_before 与 balance_after，使任意时点余额可由台账重算复现。三类变动来源：充值到账、打款出账、打款失败资金退回。",
    "payee_info": "收款信息处理（决策 A7 / A8）：本期不建收款人档案，收款信息以快照随打款单存储、不跨单复用。payee_alias 与 payee_bank_ 两组字段按 payout_method 二选一存值；两者均加密存储，界面、列表、导出一律只呈现 payee_masked。明文的解密访问需留痕（承载见 operation_log_requirement）。",
    "payout_order_status": "打款单状态机：待打款（录入提交且通过限额与余额校验后进入）；打款中（已向摩根发出指令，等待回调）；打款成功（收到摩根成功回调，终态）；打款失败（余额不足、限额拦截或摩根返回失败）；待补收款信息（失败原因属收款方不可达，等待运营更新收款信息后重回待打款）。本期无取消态与作废态。",
    "failure_handling": "打款失败分两类处置：① 可原单重发 —— 余额不足、摩根侧临时故障、超时无回调，补足资金或排除故障后在原单重发，产生新的 payout_transaction 记录，打款单号不变；② 需更换收款方式 —— 收款别名未注册、账户不存在、开户行不支持 RTP，打款单转「待补收款信息」，由运营线下联系卖家后更新收款信息。本期不接 ACH 兜底，「zelle 未注册 + 钱包未注册 + 开户行不支持 RTP」的卖家会落到第二类，此时挂起等待而非置失败，因款项客观仍然欠付（决策 A1 已接受的代价）。",
    "reconciliation": "日终对账：按 channel_transaction_id 将 payout_settlement_record 与 payout_transaction 逐笔匹配。匹配成功且金额一致则将流水 reconciliation_status 置为已结算；匹配不上或金额不符的记录留在 payout_settlement_record 并标记 match_status，进入差错处理流程直至 handle_status 闭环。「摩根侧有、我方无」的记录只存在于 payout_settlement_record，本方流水中无对应行。",
    "limit_control": "限额是本模块唯一的事前内控手段（决策 A2 不设人工审核）。打款单提交时按 payout_limit_config 中所有启用状态的规则逐条校验，任一不通过即拦截、不产生打款流水。限额的取值由运营配置，具体数值在 PRD 阶段确定。",
    "operation_log_requirement": "资金操作日志按用户决策交技术侧设计，不进产品 ER；但本模块对其提出业务约束：① 必须覆盖的动作 —— 打款单录入、打款发起、打款重发、收款信息修改、收款信息明文解密访问、充值单创建、充值到账确认、限额配置变更；② 每条须可还原「谁、何时、对哪张单、把什么值改成了什么」，并记录操作来源 IP；③ 运营与财务可按打款单号与操作人检索；④ 保留期不短于资金台账的保留期。此约束的存在理由：A2 取消了人工审核环节，事后审计成为唯一内控手段。",
    "currency": "V1 仅支持 USD，所有金额字段的 currency_code 恒为 USD。字段保留是为多币种扩展预留，本期不做汇率换算、不接汇率模块。",
    "irrevocable": "zelle 与 rtp 属终局清算、不可撤销，paypal / venmo 到账后亦不可由付款方追回。因此打款成功为终态，本模块不提供撤销与冲正能力；打错款的处置属线下追偿，不在系统内建模。",
    "no_upstream": "本期无上游回收系统对接（决策 A6），打款单不关联任何订单或回收单，与订单支付模块的表之间无外键关系。业务追溯仅依赖 payout_order.remark 自由文本（决策 A9）。",
    "ownership": "数据所有权：全部七张表均由本模块产生与维护。payout_settlement_record 的原始数据来自摩根，由本模块拉取后落库并追加匹配与处理结论。operator_id 与 handled_by 引用运营账号，为外部模块提供的只读引用，本模块不管理其生命周期。"
  }
}
